//! On-demand Studio actions and saved-file backups; no background scans.
use axum::{extract::State,Json,response::{Response,IntoResponse}};
use serde_json::{Value,json};
use std::{path::{Path,PathBuf},sync::{Mutex,atomic::Ordering},io::Read};
use sha2::{Digest,Sha256};
static BACKUP_LOCK:Mutex<()>=Mutex::new(());
fn nonce()->anyhow::Result<String>{let mut bytes=[0u8;16];getrandom::getrandom(&mut bytes).map_err(|e|anyhow::anyhow!("Identity generation failed: {e}"))?;Ok(bytes.iter().map(|x|format!("{x:02x}")).collect())}
fn root()->PathBuf {let base=std::env::var_os("LOCALAPPDATA").or_else(||std::env::var_os("XDG_CONFIG_HOME")).map(PathBuf::from).unwrap_or_else(||PathBuf::from(std::env::var_os("HOME").unwrap_or_default()).join(".config"));base.join("elio").join("backups")}
fn place(path:&Path)->anyhow::Result<PathBuf>{let path=path.canonicalize()?;anyhow::ensure!(matches!(path.extension().and_then(|x|x.to_str()).map(str::to_ascii_lowercase).as_deref(),Some("rbxl"|"rbxlx")),"Choose a saved .rbxl or .rbxlx place file.");let m=path.metadata()?;anyhow::ensure!(m.is_file()&&m.len()>0&&m.len()<=512*1024*1024,"Choose a non-empty place file up to 512 MB.");Ok(path)}
fn hash(path:&Path)->anyhow::Result<String>{let mut f=std::fs::File::open(path)?;let mut h=Sha256::new();let mut bytes=[0u8;65536];loop{let n=f.read(&mut bytes)?;if n==0{break}h.update(&bytes[..n]);}Ok(format!("{:x}",h.finalize()))}
fn backup_at(dir:&Path,path:&Path)->anyhow::Result<Value>{let original=place(path)?;std::fs::create_dir_all(dir)?;let id=nonce()?;let copy=dir.join(format!("{id}.place"));std::fs::copy(&original,&copy)?;let value=json!({"id":id,"original":original,"name":original.file_name().unwrap().to_string_lossy(),"created":std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH)?.as_secs(),"bytes":copy.metadata()?.len(),"sha256":hash(&copy)?});std::fs::write(dir.join(format!("{id}.json")),serde_json::to_vec(&value)?)?;Ok(value)}
fn backups(dir:&Path)->anyhow::Result<Value>{let mut rows=vec![];if dir.exists(){for entry in std::fs::read_dir(dir)?{let p=entry?.path();if p.extension().is_some_and(|x|x=="json"){if let Ok(v)=serde_json::from_slice::<Value>(&std::fs::read(&p)?){rows.push(v)}}}}rows.sort_by_key(|v|std::cmp::Reverse(v["created"].as_u64().unwrap_or(0)));Ok(json!({"ok":true,"records":rows}))}
fn restore_at(dir:&Path,id:&str,studio_open:bool)->anyhow::Result<Value>{anyhow::ensure!(!studio_open,"Close Roblox Studio before restoring a saved place file.");anyhow::ensure!(id.len()==32&&id.bytes().all(|x|x.is_ascii_hexdigit()),"Invalid backup.");let value:Value=serde_json::from_slice(&std::fs::read(dir.join(format!("{id}.json")))?)?;let copy=dir.join(format!("{id}.place"));anyhow::ensure!(hash(&copy)?==value["sha256"].as_str().unwrap_or(""),"Backup checksum mismatch; nothing was restored.");let original=place(Path::new(value["original"].as_str().ok_or_else(||anyhow::anyhow!("Missing original path"))?))?;let previous=backup_at(dir,&original)?;let temp=original.with_file_name(format!(".elio-restore-{}.tmp",nonce()?));std::fs::copy(copy,&temp)?;std::fs::OpenOptions::new().read(true).write(true).open(&temp)?.sync_all()?;std::fs::rename(&temp,&original)?;Ok(json!({"ok":true,"text":"Saved place restored. Reopen it in Studio. A backup of the replaced file was also saved.","previous":previous}))}
pub const ASSET_KINDS:&[(&str,&str)]=&[("model","Model"),("mesh","Mesh"),("animation","Animation"),("sound","Sound / audio"),("image","Image / decal"),("texture","Texture"),("video","Video"),("package","Package")];
pub fn parse_asset_id(v:&Value)->Option<u64>{const MAX:u64=9_007_199_254_740_991;if let Some(n)=v.as_u64(){return Some(n).filter(|x|*x>0&&*x<=MAX)}let s=v.as_str()?.trim();if s.is_empty()||s.len()>300{return None}let s=s.strip_prefix("rbxassetid://").unwrap_or(s);let all=|t:&str|!t.is_empty()&&t.len()<=16&&t.bytes().all(|b|b.is_ascii_digit());let id=if all(s){s}else if s.starts_with("https://")||s.starts_with("http://"){s.split(|c:char|c=='/'||c=='?'||c=='='||c=='&'||c=='#').find(|t|all(*t))?}else{return None};id.parse::<u64>().ok().filter(|x|*x>0&&*x<=MAX)}
const ASSET_PRELUDE:&str=r#"local sel=game:GetService('Selection'):Get()[1];if sel==game or (sel and sel.Parent==nil) then sel=nil end;local function pick(d) if sel==nil or sel:IsA('LuaSourceContainer') or sel:IsA('ValueBase') then return d end return sel end;local message='Asset added.';local function done(x,m) pcall(function() game:GetService('Selection'):Set({x}) end);message=m end;"#;
pub fn typed_asset_code(req:&Value)->anyhow::Result<String>{
 let raw=req["kind"].as_str().unwrap_or("").trim().to_ascii_lowercase();
 let kind=match raw.as_str(){"model"|"models"=>"model","mesh"|"meshes"|"meshpart"=>"mesh","animation"|"animations"|"anim"=>"animation","sound"|"sounds"|"audio"=>"sound","image"|"images"|"decal"|"decals"=>"image","texture"|"textures"=>"texture","video"|"videos"=>"video","package"|"packages"=>"package",_=>anyhow::bail!("Choose an asset type: model, mesh, animation, sound, image, texture, video or package.")};
 let id=parse_asset_id(&req["asset_id"]).ok_or_else(||anyhow::anyhow!("Enter a Roblox asset ID, rbxassetid:// link or Creator Store link."))?;
 let body=match kind{
  "model"|"package"=>r#"local a=game:GetService('InsertService'):LoadAsset(@ID@);local n=0;for _,v in ipairs(a:GetDescendants()) do if v:IsA('BaseScript') then v.Disabled=true;n+=1 end end;local out=a;local kids=a:GetChildren();if #kids==1 then out=kids[1] end;out.Parent=pick(workspace);if out~=a then a:Destroy() else a.Name='elioAsset_@ID@' end;done(out,'Inserted '..out.ClassName..' '..out:GetFullName()..'; '..n..' included scripts disabled. Review them before enabling.')"#.to_owned(),
  "mesh"=>r#"local ok,p=pcall(function() return game:GetService('AssetService'):CreateMeshPartAsync(Content.fromUri('rbxassetid://@ID@')) end);if not ok or not p then ok,p=pcall(function() return game:GetService('InsertService'):CreateMeshPartAsync('rbxassetid://@ID@',Enum.CollisionFidelity.Default,Enum.RenderFidelity.Automatic) end) end;if not ok or not p then error('Mesh asset could not be loaded: '..tostring(p)) end;p.Name='elioMesh_@ID@';p.Anchored=true;p.Parent=pick(workspace);done(p,'Inserted MeshPart '..p:GetFullName()..'.')"#.to_owned(),
  "animation"=>r#"local x=Instance.new('Animation');x.Name='elioAnimation_@ID@';x.AnimationId='rbxassetid://@ID@';x.Parent=pick(game:GetService('ReplicatedStorage'));done(x,'Added Animation '..x:GetFullName()..'. Load it with Animator:LoadAnimation.')"#.to_owned(),
  "sound"=>r#"local x=Instance.new('Sound');x.Name='elioSound_@ID@';x.SoundId='rbxassetid://@ID@';x.Parent=pick(game:GetService('SoundService'));done(x,'Added Sound '..x:GetFullName()..'.')"#.to_owned(),
  "image"|"texture"=>r#"local host=(sel and sel:IsA('BasePart')) and sel or nil;if not host then host=Instance.new('Part');host.Name='elioImageHolder_@ID@';host.Anchored=true;host.Size=Vector3.new(6,6,0.2);host.CFrame=CFrame.new(0,4,0);host.Parent=workspace end;local x=Instance.new('@CLASS@');x.Name='elio@CLASS@_@ID@';x.Texture='rbxassetid://@ID@';x.Face=Enum.NormalId.Front;x.Parent=host;done(x,'Added @CLASS@ '..x:GetFullName()..'.')"#.replace("@CLASS@",if kind=="image"{"Decal"}else{"Texture"}),
  _=>r#"local host=(sel and sel:IsA('GuiBase2d')) and sel or nil;if not host then host=Instance.new('ScreenGui');host.Name='elioVideoGui_@ID@';host.Parent=game:GetService('StarterGui') end;local x=Instance.new('VideoFrame');x.Name='elioVideo_@ID@';x.Video='rbxassetid://@ID@';x.Size=UDim2.fromScale(1,1);x.Looped=true;x.Parent=host;done(x,'Added VideoFrame '..x:GetFullName()..'.')"#.to_owned(),
 };
 Ok([ASSET_PRELUDE,&body,";return message"].concat().replace("@ID@",&id.to_string()))
}
fn code(req:&Value)->anyhow::Result<String>{let action=req["action"].as_str().unwrap_or("");Ok(match action {
 "run"=>{let c=req["code"].as_str().unwrap_or("");anyhow::ensure!(!c.trim().is_empty()&&c.len()<=32000,"Enter Luau code up to 32,000 characters.");c.to_owned()},
 "undo"=>"local h=game:GetService('ChangeHistoryService'); if h:GetCanUndo() then h:Undo(); return 'Last Studio change undone.' end; return 'No Studio change is available to undo.'".into(),
 "insert-asset"=>{let id=req["asset_id"].as_u64().filter(|x|*x>0).ok_or_else(||anyhow::anyhow!("Enter a numeric Roblox model asset ID."))?;format!("local a=game:GetService('InsertService'):LoadAsset({id}); local n=0; for _,v in ipairs(a:GetDescendants()) do if v:IsA('BaseScript') then v.Disabled=true;n+=1 end end; a.Name='elioAsset_{id}';a.Parent=workspace;return 'Inserted model; '..n..' included scripts disabled. Review them in Studio before enabling.'")},
 "insert-typed-asset"=>typed_asset_code(req)?,
 "lighting"=>{let (clock,brightness,ambient,fog)=match req["preset"].as_str().unwrap_or(""){"Sunny day"=>(14.0,2.0,"128,128,128",100000),"Golden sunset"=>(17.8,2.0,"150,100,70",3000),"Night"=>(0.0,1.0,"35,45,75",3000),"Foggy horror"=>(1.0,0.6,"45,55,50",160),"Neon city"=>(23.0,1.8,"75,40,110",2000),"Cartoon bright"=>(12.0,3.0,"160,160,160",100000),_=>anyhow::bail!("Choose a lighting preset.")};format!("local l=game:GetService('Lighting');l.ClockTime={clock};l.Brightness={brightness};l.Ambient=Color3.fromRGB({ambient});l.OutdoorAmbient=l.Ambient;l.FogEnd={fog};return 'Lighting preset applied.'")},
 "terrain"=>{let preset=req["preset"].as_str().unwrap_or("");anyhow::ensure!(["Island","Mountains","Desert dunes","Snowy hills","Plains + lake"].contains(&preset),"Choose a terrain preset.");let side=match req["size"].as_str().unwrap_or("Medium"){"Small"=>128,"Medium"=>256,"Large"=>384,_=>anyhow::bail!("Choose Small, Medium or Large.")};let seed=req["seed"].as_i64().filter(|v|(-2147483648..=2147483647).contains(v)).ok_or_else(||anyhow::anyhow!("Enter a whole-number seed."))?;let material=match preset{"Desert dunes"=>"Sand","Snowy hills"=>"Snow","Mountains"=>"Rock",_=>"Grass"};let height=match preset{"Mountains"=>"16+math.abs(n)*120","Snowy hills"=>"16+math.abs(n)*72","Desert dunes"=>"12+math.abs(n)*40","Island"=>"math.max(4,48*(1-math.sqrt(x*x+z*z)/(side*.43))+n*20)",_=>"12+n*14"};let clear=if req["replace"].as_bool().unwrap_or(false){"t:FillBlock(CFrame.new(0,96,0),Vector3.new(side,256,side),Enum.Material.Air)"}else{""};format!("local t=workspace.Terrain;local side={side};local seed={seed};{clear};local cells=0;for x=-side/2+8,side/2-8,16 do for z=-side/2+8,side/2-8,16 do local n=math.noise(x/80,z/80,seed/1000);local h=math.max(4,{height});t:FillBlock(CFrame.new(x,h/2-16,z),Vector3.new(16,h,16),Enum.Material.{material});if {water} and h<24 then t:FillBlock(CFrame.new(x,-4,z),Vector3.new(16,24,16),Enum.Material.Water) end;cells+=1 end end;return 'Terrain generated: '..cells..' columns; seed {seed}.'",water=if matches!(preset,"Island"|"Plains + lake"){"true"}else{"false"})},
 "health"=>include_str!("toolkit-health.luau").into(),
 _=>anyhow::bail!("Unknown Toolkit action.")})}
pub async fn post(State(state):State<crate::AppState>,Json(req):Json<Value>)->Response{
 let action_name=req["action"].as_str().unwrap_or("").to_owned();let result: anyhow::Result<Value>=async{
  let action=action_name.as_str();
  if !matches!(action,"health"|"backups"){crate::safety::mutation()?;}
  if matches!(action,"backups"|"backup"|"restore") {let open=state.roblox_proc.load(Ordering::Relaxed)||state.roblox_editor_connected.load(Ordering::Relaxed);return tokio::task::spawn_blocking(move||{let _guard=BACKUP_LOCK.lock().unwrap_or_else(|e|e.into_inner());let dir=root();match req["action"].as_str().unwrap_or(""){"backups"=>backups(&dir),"backup"=>Ok(json!({"ok":true,"record":backup_at(&dir,Path::new(req["path"].as_str().unwrap_or("")))?,"text":"Saved place backup created. Unsaved Studio edits are not included."})),_=>restore_at(&dir,req["id"].as_str().unwrap_or(""),open)}}).await?;}
  anyhow::ensure!(state.roblox_editor_connected.load(Ordering::Relaxed),"Connect Roblox Studio and open a place first.");
  anyhow::ensure!(state.mcp_in_flight.load(Ordering::Relaxed)==0,"A Studio command is running. Wait for it to finish.");
  let (name,args)=if matches!(action,"play"|"stop-play"){("start_stop_play",json!({"is_start":action=="play"}))}else{let c=code(&req)?;let dm=if action=="run"{match req["datamodel"].as_str().unwrap_or("Edit"){"Edit"=>"Edit","Server"=>"Server","Client"=>"Client",_=>anyhow::bail!("Choose Edit, Server or Client.")}}else{"Edit"};let c=if !matches!(action,"undo"|"health")&&dm=="Edit"{format!("local h=game:GetService('ChangeHistoryService');pcall(function() h:SetWaypoint('Before elio Toolkit') end);local result=(function() {c} end)();pcall(function() h:SetWaypoint('elio Toolkit') end);return result")}else{c};("execute_luau",json!({"code":c,"datamodel_type":dm}))};
  let out=crate::roblox_tool(&state,name,args).await?;Ok(json!({"ok":true,"text":out.text,"images":out.images}))
 }.await;
 match result{Ok(v)=>Json(v).into_response(),Err(e)=>(axum::http::StatusCode::BAD_REQUEST,Json(json!({"ok":false,"error":e.to_string()}))).into_response()}
}
#[cfg(test)]mod tests{use super::*;
 #[test]fn validate_controls_and_seed(){assert!(code(&json!({"action":"terrain","preset":"Island","size":"Medium","seed":0})).unwrap().contains("seed=0"));assert!(code(&json!({"action":"terrain","preset":"bad","seed":1})).is_err());assert!(code(&json!({"action":"insert-asset","asset_id":"1;evil"})).is_err());assert!(code(&json!({"action":"run","code":""})).is_err());assert!(code(&json!({"action":"lighting","preset":"bad"})).is_err());}
 #[test]fn typed_asset_upload_kinds(){for k in ["model","mesh","animation","sound","image","texture","video","package","Audio","decal"]{let c=code(&json!({"action":"insert-typed-asset","kind":k,"asset_id":"rbxassetid://123456"})).unwrap();assert!(c.contains("123456"),"{k}");assert!(!c.contains("@ID@")&&!c.contains("@CLASS@"),"{k}");}assert!(code(&json!({"action":"insert-typed-asset","kind":"sound","asset_id":"https://create.roblox.com/store/asset/987654/Boom"})).unwrap().contains("SoundId='rbxassetid://987654'"));assert!(code(&json!({"action":"insert-typed-asset","kind":"sound","asset_id":"1;evil"})).is_err());assert!(code(&json!({"action":"insert-typed-asset","kind":"sound","asset_id":"rbxassetid://1')evil"})).is_err());assert!(code(&json!({"action":"insert-typed-asset","kind":"script","asset_id":5})).is_err());assert!(code(&json!({"action":"insert-typed-asset","kind":"sound","asset_id":0})).is_err());assert!(code(&json!({"action":"insert-typed-asset","kind":"animation","asset_id":7})).unwrap().contains("Instance.new('Animation')"));assert!(code(&json!({"action":"insert-typed-asset","kind":"image","asset_id":7})).unwrap().contains("Instance.new('Decal')"));assert_eq!(ASSET_KINDS.len(),8);}
 #[test]fn backup_restore_checksums_and_open_studio(){let dir=std::env::temp_dir().join(format!("elio-toolkit-{}",nonce().unwrap()));std::fs::create_dir_all(&dir).unwrap();let file=dir.join("sample.rbxl");std::fs::write(&file,b"saved place").unwrap();let row=backup_at(&dir.join("copies"),&file).unwrap();let id=row["id"].as_str().unwrap();std::fs::write(&file,b"new version").unwrap();assert!(restore_at(&dir.join("copies"),id,true).is_err());assert_eq!(std::fs::read(&file).unwrap(),b"new version");restore_at(&dir.join("copies"),id,false).unwrap();assert_eq!(std::fs::read(&file).unwrap(),b"saved place");std::fs::write(dir.join("copies").join(format!("{id}.place")),b"tampered").unwrap();assert!(restore_at(&dir.join("copies"),id,false).is_err());assert!(restore_at(&dir,"../x",false).is_err());std::fs::remove_dir_all(dir).unwrap();}
}
